#!/usr/bin/env bash
set -euo pipefail
base64 -d > /tmp/fixup_3rivers.py <<'FIX_B64'

FIX_B64
set -a; . /etc/3rivers/bisera.env; set +a
sudo -u three_rivers --preserve-env=BISERADB_BASE_URL,BISERADB_NAMESPACE,BISERADB_API_KEY /opt/3rivers/app/venv/bin/python /tmp/fixup_3rivers.py
rm -f /tmp/fixup_3rivers.py
